def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    people_patches = image_patch.find("person")
    bags_patches = image_patch.find("bag")
    guy_patches = image_patch.find("guy")

    if not people_patches: return image_patch
    if not bags_patches: return people_patches[0]
    if not guy_patches: return bags_patches[0]

    guy_center_x = guy_patches[0].horizontal_center
    guy_center_y = guy_patches[0].vertical_center

    closest_person = None
    closest_bag = None

    for person in people_patches:
        if abs(person.horizontal_center - guy_center_x) < 10 and abs(person.vertical_center - guy_center_y) < 10:
            if closest_person is None or person.distance(guy_patches[0]) < closest_person.distance(guy_patches[0]):
                closest_person = person

    for bag in bags_patches:
        if abs(bag.horizontal_center - guy_center_x) < 10 and abs(bag.vertical_center - guy_center_y) < 10:
            if closest_bag is None or bag.distance(guy_patches[0]) < closest_bag.distance(guy_patches[0]):
                closest_bag = bag

    if closest_person is not None:
        return closest_person
    elif closest_bag is not None:
        return closest_bag
    else:
        return image_patch

def execute_command(image) -> ImagePatch:
