    hat_center = hat_patches[0].horizontal_center
    coat_center = coat_patches[0].horizontal_center
    if hat_center < coat_center:
        return hat_patches[0]
    elif coat_center < hat_center:
        return coat_patches[0]
    else:
        return image_patch

def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    man_patches = image_patch.find("man")
    man_patches.sort(key=lambda p: p.horizontal_center)
    woman_patches = image_patch.find("woman")
    woman_patches.sort(key=lambda p: p.horizontal_center)

    for woman in woman_patches:
        for man in man_patches:
            if woman.overlaps_with(man.left, man.lower, man.right, man.upper):
                return woman
    return None

